CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS stores(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT UNIQUE NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,pickup_enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','STORE_MANAGER','STORE_STAFF')),store_id UUID REFERENCES stores(id),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS permissions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,permission TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(user_id,permission));
CREATE TABLE IF NOT EXISTS products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),sku TEXT UNIQUE,barcode TEXT UNIQUE,name TEXT NOT NULL,description TEXT,category TEXT,brand TEXT,cost_price NUMERIC(12,2) DEFAULT 0,retail_price NUMERIC(12,2) DEFAULT 0,wholesale_price NUMERIC(12,2),wholesale_min_qty INTEGER DEFAULT 1,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),store_id UUID REFERENCES stores(id) ON DELETE CASCADE,product_id UUID REFERENCES products(id) ON DELETE CASCADE,quantity INTEGER DEFAULT 0,reserved_quantity INTEGER DEFAULT 0,reorder_level INTEGER DEFAULT 0,batch_number TEXT,expiry_date DATE,UNIQUE(store_id,product_id,batch_number));
CREATE TABLE IF NOT EXISTS vip_customers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,business_name TEXT,phone TEXT NOT NULL,email TEXT,address TEXT,status TEXT DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED','SUSPENDED')),approved_by UUID REFERENCES users(id),approved_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_methods(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),store_id UUID REFERENCES stores(id) ON DELETE CASCADE,name TEXT NOT NULL,account_name TEXT,account_number TEXT,bank_name TEXT,instructions TEXT,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),store_id UUID REFERENCES stores(id),vip_customer_id UUID REFERENCES vip_customers(id),customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,fulfillment TEXT CHECK(fulfillment IN('PICKUP','DELIVERY')),delivery_address TEXT,payment_method_id UUID REFERENCES payment_methods(id),payment_status TEXT DEFAULT 'PENDING',order_status TEXT DEFAULT 'PENDING',subtotal NUMERIC(12,2) DEFAULT 0,delivery_fee NUMERIC(12,2) DEFAULT 0,total NUMERIC(12,2) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID REFERENCES orders(id) ON DELETE CASCADE,product_id UUID REFERENCES products(id),quantity INTEGER CHECK(quantity>0),unit_price NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS stock_transfers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),from_store_id UUID REFERENCES stores(id),to_store_id UUID REFERENCES stores(id),product_id UUID REFERENCES products(id),quantity INTEGER CHECK(quantity>0),status TEXT DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),store_id UUID REFERENCES stores(id),description TEXT NOT NULL,amount NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id UUID REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT,entity_id UUID,store_id UUID REFERENCES stores(id),details JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_operations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),client_operation_id TEXT UNIQUE NOT NULL,user_id UUID REFERENCES users(id),store_id UUID REFERENCES stores(id),operation_type TEXT NOT NULL,payload JSONB NOT NULL,status TEXT DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT now());
